static z_t551_t z_t92_lastIndexOf(const z_t92_t* self, const z_t92_t* needle);
static z_t551_t z_t92_lastIndexOf(const z_t92_t* self, const z_t92_t* needle) {
    z_t551_t out = {0};
    if (needle->size == 0) {
        out.tag = Z_T551_TAG_1;
        out.data.a1 = self->size;
        return out;
    }
    if (needle->size > self->size) {
        out.tag = Z_T551_TAG_0;
        return out;
    }
    for (uint64_t i = self->size - needle->size + 1; i > 0; i--) {
        uint64_t idx = i - 1;
        if (memcmp(self->data + idx, needle->data, needle->size) == 0) {
            out.tag = Z_T551_TAG_1;
            out.data.a1 = idx;
            return out;
        }
    }
    out.tag = Z_T551_TAG_0;
    return out;
}


